import{_ as t,o as i,c as o,ae as s}from"./chunks/framework.sgRordCm.js";const a="/heidrun/screenshots/features/file_explorer.png",r="/heidrun/screenshots/features/source_control.png",n="/heidrun/screenshots/features/code_hosting.png",h="/heidrun/screenshots/features/launchers.png",d="/heidrun/screenshots/features/clipboard.png",g=JSON.parse('{"title":"The sidebar sections","description":"","frontmatter":{},"headers":[],"relativePath":"features/sidebar_sections.md","filePath":"features/sidebar_sections.md"}'),c={name:"features/sidebar_sections.md"};function l(u,e,p,f,b,m){return i(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="the-sidebar-sections" tabindex="-1">The sidebar sections <a class="header-anchor" href="#the-sidebar-sections" aria-label="Permalink to &quot;The sidebar sections&quot;">​</a></h1><p>Around your coding agents, you need more: the files of the project, the Git changes, the issues, the commands of the project, and the pieces of text that you want to keep. Without Heidrun, each one is in a different application.</p><h2 id="what-heidrun-does" tabindex="-1">What Heidrun does <a class="header-anchor" href="#what-heidrun-does" aria-label="Permalink to &quot;What Heidrun does&quot;">​</a></h2><p>The left sidebar and the right sidebar each hold several sidebar sections. The sidebar icon bar, at the outer edge of each sidebar, shows one icon for each sidebar section. Click an icon to show its sidebar section.</p><h2 id="file-explorer-sidebar-section" tabindex="-1">File explorer sidebar section <a class="header-anchor" href="#file-explorer-sidebar-section" aria-label="Permalink to &quot;File explorer sidebar section&quot;">​</a></h2><p>The File explorer sidebar section, in the left sidebar, shows the whole folder tree of the Git repository of the selected workspace.</p><ul><li>Click a folder to fold it or to unfold it.</li><li>Click a file to open it in the Files window, where you can read the file and edit it. The keys ⌘P find a file by its name.</li><li>The option &quot;Ignored files&quot; of its menu shows or hides the files that Git ignores.</li></ul><p><img src="'+a+'" alt="The File explorer sidebar section with the folders and the files at the root of the repository." width="300"></p><h2 id="source-control-sidebar-section" tabindex="-1">Source control sidebar section <a class="header-anchor" href="#source-control-sidebar-section" aria-label="Permalink to &quot;Source control sidebar section&quot;">​</a></h2><p>The Source control sidebar section, in the left sidebar, shows the Git changes of the selected workspace, as the source control view of Visual Studio Code does.</p><ul><li>Stage the files, write the commit message, and press ⌘Enter to commit.</li><li>The menu of the commit button also gives &quot;Commit and push&quot;, and &quot;Commit (amend the last commit)&quot;.</li><li>The sparkle button asks a coding agent to write the commit message from the diff. See <a href="/heidrun/features/ai.html">The use of AI</a>.</li><li>The large Git window shows the diff of every change, with the open pull requests in a side list.</li></ul><p><img src="'+r+'" alt="The Source control sidebar section with the commit message box, the commit button, and the list of the changed files." width="300"></p><h2 id="code-hosting-sidebar-section" tabindex="-1">Code hosting sidebar section <a class="header-anchor" href="#code-hosting-sidebar-section" aria-label="Permalink to &quot;Code hosting sidebar section&quot;">​</a></h2><p>The Code hosting sidebar section, in the left sidebar, shows the open issues and the open pull requests of GitHub, or the merge requests of GitLab, for the repository of the selected workspace.</p><ul><li>Click a row to read more about the issue or the pull request in an information card.</li><li>Type in the search field to find an item, and save a search that you use often.</li></ul><p><img src="'+n+'" alt="The Code hosting sidebar section with the search field and the list of the open issues of the repository." width="300"></p><h2 id="launchers-sidebar-section" tabindex="-1">Launchers sidebar section <a class="header-anchor" href="#launchers-sidebar-section" aria-label="Permalink to &quot;Launchers sidebar section&quot;">​</a></h2><p>The Launchers sidebar section, in the left sidebar, lists the launchers of the selected workspace. A launcher is a name, a command line, and an optional folder.</p><ul><li>Click &quot;Run&quot; to run the command line of a launcher in its own tab.</li><li>Import launchers from the scripts of the file <code>package.json</code> in one click.</li><li>Create a custom launcher that runs a command line, or a coding agent with a prompt.</li></ul><p>Heidrun saves the launchers in the file <code>.heidrun/config.json</code> of the repository, so your team shares them.</p><p><img src="'+h+'" alt="The Launchers sidebar section with five launchers, each with its description and its button Run." width="300"></p><h2 id="clipboard-sidebar-section" tabindex="-1">Clipboard sidebar section <a class="header-anchor" href="#clipboard-sidebar-section" aria-label="Permalink to &quot;Clipboard sidebar section&quot;">​</a></h2><p>The Clipboard sidebar section, in the right sidebar, lists the notes that you pinned from the text of a terminal. Find a command, an error, or an answer again later. The switch &quot;All workspaces&quot; shows the notes of every workspace.</p><p><img src="'+d+'" alt="The Clipboard sidebar section with two notes pinned from the text of two terminals, each with its buttons Copy and Send to." width="300"></p><p><em>A Viking keeps the axe, the shield, and the horn of mead within reach. You keep your files, your branches, and your issues within reach.</em></p>',25)])])}const _=t(c,[["render",l]]);export{g as __pageData,_ as default};
